import{_ as e,o as r,c as o,a2 as n}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Prompt Engineering","description":"Prompt Engineering reference documentation","frontmatter":{"title":"Prompt Engineering","description":"Prompt Engineering reference documentation"},"headers":[],"relativePath":"knowledge/prompt-engineering.md","filePath":"knowledge/prompt-engineering.md","lastUpdated":1784485118000}'),i={name:"knowledge/prompt-engineering.md"};function a(s,t,l,p,d,c){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="prompt-engineering" tabindex="-1">Prompt Engineering <a class="header-anchor" href="#prompt-engineering" aria-label="Permalink to &quot;Prompt Engineering&quot;">​</a></h1><h1 id="prompt-engineering-—-knowledge-base" tabindex="-1">Prompt Engineering — Knowledge Base <a class="header-anchor" href="#prompt-engineering-—-knowledge-base" aria-label="Permalink to &quot;Prompt Engineering — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Prompt engineering is the practice of designing inputs to LLMs that produce desired outputs consistently and reliably. This knowledge base covers prompt design principles, patterns, optimization techniques, and testing strategies for building AI features with predictable quality.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="prompt-structure" tabindex="-1">Prompt Structure <a class="header-anchor" href="#prompt-structure" aria-label="Permalink to &quot;Prompt Structure&quot;">​</a></h3><p><strong>System prompt</strong> — Sets the model&#39;s role, behavior, constraints, and output format. This is the foundation of consistent behavior.</p><p><strong>User prompt</strong> — The actual task or query. Should be specific, contextual, and unambiguous.</p><p><strong>Context window</strong> — Limited token budget for the entire conversation; prioritize the most relevant information.</p><h3 id="prompt-patterns" tabindex="-1">Prompt Patterns <a class="header-anchor" href="#prompt-patterns" aria-label="Permalink to &quot;Prompt Patterns&quot;">​</a></h3><p><strong>Zero-shot</strong> — Give the task directly without examples. Works for simple, well-defined tasks.</p><p><strong>Few-shot</strong> — Provide 2-5 input/output examples demonstrating the desired behavior. Essential for complex formatting or nuanced tasks.</p><p><strong>Chain-of-thought (CoT)</strong> — Ask the model to reason step-by-step before providing an answer. Improves accuracy for reasoning tasks.</p><p><strong>Role prompting</strong> — Assign a specific role to the model (&quot;You are a senior TypeScript developer...&quot;). Focuses domain expertise.</p><p><strong>Self-consistency</strong> — Generate multiple responses and select the most common answer. Improves reliability for critical decisions.</p><h3 id="structured-output" tabindex="-1">Structured Output <a class="header-anchor" href="#structured-output" aria-label="Permalink to &quot;Structured Output&quot;">​</a></h3><p><strong>JSON mode</strong> — Force responses in valid JSON format. Use for data extraction and API integration.</p><p><strong>Function calling</strong> — Define expected output as a function schema. Model generates structured arguments matching the schema.</p><p><strong>Template-based</strong> — Provide output templates with placeholders for the model to fill.</p><h3 id="token-management" tabindex="-1">Token Management <a class="header-anchor" href="#token-management" aria-label="Permalink to &quot;Token Management&quot;">​</a></h3><ul><li><strong>Input tokens</strong> — Text in prompts (system + user + context). Charged per token.</li><li><strong>Output tokens</strong> — Model&#39;s response. Usually more expensive than input tokens.</li><li><strong>Context window limit</strong> — Maximum tokens per request (4K to 200K depending on model).</li><li><strong>Tokenization</strong> — Text is split into tokens; words may be multiple tokens; Arabic tokenization differs from English.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Be specific and explicit</strong> — Vague prompts produce vague outputs; state exactly what you want, the format, length, and constraints</li><li><strong>Use structured output consistently</strong> — Always define expected output format with JSON schema or function calling; never parse free-form text for critical data</li><li><strong>Provide few-shot examples for complex tasks</strong> — Show 2-3 input/output pairs for tasks with specific formatting, tone, or reasoning patterns</li><li><strong>Use chain-of-thought for reasoning</strong> — Ask &quot;think step by step&quot; for math, logic, comparison, and multi-step reasoning tasks</li><li><strong>Separate instructions from data</strong> — Keep system prompts for behavior rules; user prompts for task-specific data; don&#39;t mix concerns</li><li><strong>Version and test prompts</strong> — Treat prompts as code; version them in Git, test with representative inputs, and track quality metrics</li><li><strong>Implement output validation</strong> — Always validate LLM output against expected schema; retry on invalid responses</li><li><strong>Optimize for cost and latency</strong> — Shorter prompts cost less and respond faster; remove unnecessary context while maintaining quality</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Vague instructions</strong> — &quot;Make it good&quot; is unactionable; specify criteria, format, and constraints explicitly</li><li><strong>Overloading context window</strong> — Filling the entire context with irrelevant information degrades performance; include only necessary context</li><li><strong>Ignoring model limitations</strong> — LLMs don&#39;t have real-time data, can&#39;t access external systems (without tools), and may hallucinate</li><li><strong>Using the same prompt for all models</strong> — Different models respond differently; optimize prompts per model family</li><li><strong>Not handling format failures</strong> — LLMs sometimes produce invalid JSON or miss format requirements; implement retry with format correction</li><li><strong>Hardcoded prompts in code</strong> — Prompts scattered across codebase are hard to manage; store in dedicated config or database</li><li><strong>Skipping edge case testing</strong> — Prompts that work for normal input may fail for empty, malicious, or unusual input</li><li><strong>Not setting temperature</strong> — Temperature controls randomness; use 0 for factual tasks, 0.7-1.0 for creative tasks</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not defining output format upfront</strong> — Adding format requirements after development causes inconsistency; define format in system prompt from the start</li><li><strong>Ignoring token costs</strong> — Long prompts with few-shot examples multiply costs; optimize prompt length for production</li><li><strong>Using &quot;please&quot; and politeness markers</strong> — They waste tokens without improving output quality; be direct and technical</li><li><strong>Not handling model updates</strong> — Model behavior changes with updates; pin model versions and test when updating</li><li><strong>Including sensitive data in prompts</strong> — User data in prompts may be stored by providers; sanitize PII before sending</li><li><strong>Forgetting Arabic/English differences</strong> — LLMs perform differently across languages; test prompts in both languages</li><li><strong>Not retrying on format failures</strong> — First attempt may produce malformed output; implement retry loop with format validation</li><li><strong>Using max tokens as a safety net</strong> — Setting very high max tokens wastes budget; estimate appropriate limits per task type</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task Type</th><th>Recommended Pattern</th></tr></thead><tbody><tr><td>Classification</td><td>Few-shot with 3-5 examples, structured output</td></tr><tr><td>Data extraction</td><td>Function calling with strict JSON schema</td></tr><tr><td>Summarization</td><td>System prompt with length/format constraints</td></tr><tr><td>Creative writing</td><td>Higher temperature, minimal constraints</td></tr><tr><td>Code generation</td><td>Role prompting + few-shot + chain-of-thought</td></tr><tr><td>Q&amp;A / Research</td><td>Chain-of-thought, cite sources, temperature 0</td></tr><tr><td>Translation</td><td>System prompt with target language, few-shot pairs</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>OpenAI Prompt Engineering Guide: <a href="https://platform.openai.com/docs/guides/prompt-engineering" target="_blank" rel="noreferrer">https://platform.openai.com/docs/guides/prompt-engineering</a></li><li>Anthropic Prompt Engineering: <a href="https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering</a></li><li>Prompt Engineering Guide: <a href="https://www.promptingguide.ai/" target="_blank" rel="noreferrer">https://www.promptingguide.ai/</a></li><li>Google Vertex AI Prompt Design: <a href="https://cloud.google.com/vertex-ai/docs/generative-ai/prompt-design" target="_blank" rel="noreferrer">https://cloud.google.com/vertex-ai/docs/generative-ai/prompt-design</a></li><li>LangChain Prompt Templates: <a href="https://js.langchain.com/docs/concepts/prompt-templates/" target="_blank" rel="noreferrer">https://js.langchain.com/docs/concepts/prompt-templates/</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>System prompt template:</strong> Start with role definition, then constraints, then output format, then examples</li><li><strong>Testing framework:</strong> Create a test suite with representative inputs; measure accuracy, format compliance, and latency</li><li><strong>Production prompts:</strong> Store in database or config files; enable A/B testing without code deployments</li><li><strong>Arabic prompts:</strong> Test with Arabic inputs separately; model performance may vary; consider translation for critical tasks</li><li><strong>Cost optimization:</strong> Use shorter prompts for high-volume features; cache responses for repeated queries</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',35)])])}const u=e(i,[["render",a]]);export{g as __pageData,u as default};
